def lpHaarNormalizedBlockEntry (T : IntervalLp 𝕜 p →L[𝕜] IntervalLp 𝕜 p)
    (S R : LpHaarFiniteSplit) : 𝕜 :=
  (‖S.vector 𝕜 p‖ : 𝕜) * (‖R.vector 𝕜 p‖ : 𝕜)⁻¹ * S.reader 𝕜 p (T (R.vector 𝕜 p))

